package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func hashToken(token string) string {
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:])
}

// validateSession checks bearer token against sessions table
func validateSession(r *http.Request) (string, bool) {
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, "Bearer ") {
		return "", false
	}
	token := strings.TrimPrefix(auth, "Bearer ")
	tokenHash := hashToken(token)
	var userID string
	err := db.QueryRow("SELECT user_id FROM sessions WHERE token_hash=$1 AND expires_at > NOW()", tokenHash).Scan(&userID)
	if err != nil {
		return "", false
	}
	return userID, true
}

// reportHandler generates reports with user-controlled template name and filter
func reportHandler(w http.ResponseWriter, r *http.Request) {
	userID, ok := validateSession(r)
	if !ok {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	reportType := r.URL.Query().Get("type")
	if reportType == "" {
		reportType = "summary"
	}

	// Filter by department - user controlled
	dept := r.URL.Query().Get("dept")
	if dept == "" {
		dept = "all"
	}

	// Build query - dept is validated against known list
	validDepts := map[string]bool{"engineering": true, "sales": true, "hr": true, "finance": true, "all": true}
	if !validDepts[strings.ToLower(dept)] {
		http.Error(w, "invalid department", http.StatusBadRequest)
		return
	}

	// Sort parameter - VULNERABLE: directly interpolated into ORDER BY
	sortCol := r.URL.Query().Get("sort")
	if sortCol == "" {
		sortCol = "created_at"
	}

	var query string
	if dept == "all" {
		query = fmt.Sprintf("SELECT id, title, amount, department, created_at FROM expenses WHERE requester_id = '%s' ORDER BY %s DESC LIMIT 50", userID, sortCol)
	} else {
		query = fmt.Sprintf("SELECT id, title, amount, department, created_at FROM expenses WHERE requester_id = '%s' AND department = '%s' ORDER BY %s DESC LIMIT 50", userID, dept, sortCol)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error for user %s: %v", userID, err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	type Expense struct {
		ID, Title, Department string
		Amount                float64
		CreatedAt             string
	}
	var expenses []Expense
	for rows.Next() {
		var e Expense
		rows.Scan(&e.ID, &e.Title, &e.Amount, &e.Department, &e.CreatedAt)
		expenses = append(expenses, e)
	}

	// Template rendering - reportType used to select template
	tmplFile := fmt.Sprintf("templates/report_%s.html", reportType)
	if _, err := os.Stat(tmplFile); os.IsNotExist(err) {
		tmplFile = "templates/report_summary.html"
	}

	tmpl, err := template.ParseFiles(tmplFile)
	if err != nil {
		http.Error(w, "template error", http.StatusInternalServerError)
		return
	}

	data := map[string]interface{}{"User": userID, "Expenses": expenses, "Dept": dept}
	tmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/reports", reportHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
